"""Probes pyexpat (through xml.etree.ElementTree.fromstring, as winevt_parser.py uses it) for the non-ASCII XML name
characters and writes them as Go range tables.

    python3 receiver/parse/testdata/wp5gen/gen_names.py > receiver/parse/winevt_names.go
"""
import pyexpat
import xml.etree.ElementTree as ET


def ok(s):
    try:
        ET.fromstring(s)
        return True
    except ET.ParseError:
        return False


def ranges(cs):
    out = []
    for c in cs:
        if out and out[-1][1] == c - 1:
            out[-1][1] = c
        else:
            out.append([c, c])
    return out


cps = [c for c in range(0x80, 0x110000) if not 0xD800 <= c < 0xE000]
start = ranges([c for c in cps if ok("<" + chr(c) + "/>")])
char = ranges([c for c in cps if ok("<a" + chr(c) + "/>")])

print("// Code generated by receiver/parse/testdata/wp5gen/gen_names.py from pyexpat %s. DO NOT EDIT." % pyexpat.EXPAT_VERSION)
print()
print("package parse")
print()
for n, (name, rs) in enumerate((("xmlNameStartRanges", start), ("xmlNameCharRanges", char))):
    if n:
        print()
    print("// %s: non-ASCII code points expat accepts %s (sorted, inclusive)." % (name, "at the start of an XML name" if "Start" in name else "inside an XML name"))
    print("var %s = [][2]rune{" % name)
    for i in range(0, len(rs), 6):
        print("\t" + " ".join("{0x%04X, 0x%04X}," % (a, b) for a, b in rs[i:i + 6]))
    print("}")
